 if(kind==17){if(!data)return;U app=p.read(0x7a39fc),array=p.objects(p.read(app+8));if(!array)return;U id=p.read(data);if((p.lookup(array,id,q+0x14)&255)!=0)return;U obj=p.placeable(p.read(q+0x14));if(!obj)return;U pos=data+4;p.place(obj,s,pos,0);if(!p.read(obj+0x44c))return;for(U off:{0x28u,0x2cu,0x30u,0x1cu,0x20u,0x24u})p.write(q+off,0);p.bounds(obj+0x3a0,q+0x28,q+0x1c);p.position_update(s,pos,q+0x28,q+0x1c,0x7f000000,0);return;}
 if(kind==5){if(!data||p.read16(data+8)!=30)return;U z=p.effect_real(data,2);p.write(q+0x10,z);U y=p.effect_real(data,1);p.write(q+0x14,y);U x=p.effect_real(data,0);p.write(q+0x1c,x);y=p.read(q+0x14);z=p.read(q+0x10);p.write(q+0x20,y);p.write(q+0x24,z);p.write(q+0x28,0);p.write(q+0x2c,0);p.write(q+0x30,0);p.effect(s,data,q+0x1c,q+0x28);return;}
 if(kind==10){U sub=p.read16(data),id=0,name=0;if(sub==0){id=p.read(s+0x120);p.write(s+0x13c,day);p.write(s+0x140,tick);name=s+0x164;}else if(sub==11){U v=p.integer(data,0);id=p.read(s+0x120);p.write(s+0x1dc,v);name=s+0x16c;}else if(sub==12){p.write(s+0x1d4,source);U app=p.read(0x7a39fc),old=p.mode(p.read(app+8));app=p.read(0x7a39fc);U server=p.read(app+8);U v=p.integer(data,0);p.set_mode(server,v);id=p.read(s+0x120);p.script(p.read(0x7a3a00),s+0x174,id,1);app=p.read(0x7a39fc);p.set_mode(p.read(app+8),old);}else if(sub==13){id=p.read(s+0x120);p.write(s+0x1d8,source);name=s+0x17c;}if(name)p.script(p.read(0x7a3a00),name,id,1);p.destroy(data);p.release(data);return;}
 if(kind!=26)return;
 if(p.read(s+0x2c4)){U captured=p.read8(s+0x2c9);if(p.integer(data,0)==captured){U app=p.read(0x7a39fc);p.set_transition(p.read(app+8),1);U text=p.string(data,q+0x14,0);app=p.read(0x7a39fc);p.set_module(p.read(app+8),text);p.string_destroy(q+0x14);text=p.string(data,q+0x14,1);app=p.read(0x7a39fc);p.set_waypoint(p.read(app+8),text);p.string_destroy(q+0x14);p.write(q+0x10,6);U i=2;do{text=p.string(data,q+0x14,i);app=p.read(0x7a39fc);p.movie(p.read(app+4),text);p.string_destroy(q+0x14);U remaining=p.read(q+0x10);++i;--remaining;p.write(q+0x10,remaining);if(!remaining)break;}while(true);p.write(s+0x2c4,0);p.byte(s+0x2c9,0);app=p.read(0x7a39fc);p.input(p.read(app+4),1,0);}}
 else {U event=p.allocate(0x34);p.write(q+0x14,event);if(event)event=p.construct(event);p.write(q+0x10,event);U token=p.next(s)&255;event=p.read(q+0x10);p.byte(q+0xf,token);p.integer_set(event,0,token);p.write(q+0x14,8);U i=0;do{U text=p.string(data,q+0x1c,i);U target=p.read(q+0x10);p.string_set(target,i,text);p.string_destroy(q+0x1c);U remaining=p.read(q+0x14);++i;--remaining;p.write(q+0x14,remaining);if(!remaining)break;}while(true);U app=p.read(0x7a39fc),server=p.read(app+8);event=p.read(q+0x10);U id=p.read(s+0x120);p.enqueue(p.ai(server),0,500,id,id,26,event);app=p.read(0x7a39fc);p.write(q+0x34,0);p.write(q+0x38,0);p.write(q+0x3c,0);U gui=p.gui(p.read(app+4));p.fade(gui,0,0,0x3f000000,q+0x34);token=p.read8(q+0xf);p.write(s+0x2c4,1);p.byte(s+0x2c9,token);app=p.read(0x7a39fc);p.input(p.read(app+4),0,1);}
